using System;using System.Linq;using System.Collections.Generic;using Mirror;
namespace MultiFPS {
// Session-only membership. No profiles, wallet IDs, JSON or transcript storage.
public static class RiftSessionParty {
 sealed class Group{public uint Leader,Version;public readonly List<uint> Members=new List<uint>();}
 sealed class Invitation{public uint From,Token,Version,TargetEpoch;public Group Group;public double Until;}
 static readonly Dictionary<uint,Group> groups=new Dictionary<uint,Group>();static readonly Dictionary<uint,Invitation> invites=new Dictionary<uint,Invitation>();static readonly Dictionary<uint,uint> epochs=new Dictionary<uint,uint>();static uint sequence;static double nextTick;
 public static int RoomLimit(MultiFPS.Gameplay.Gamemodes.Gamemodes mode,int requested)=>mode==MultiFPS.Gameplay.Gamemodes.Gamemodes.Raid?UnityEngine.Mathf.Clamp(requested,1,4):requested;
 public static bool CanAdmit(MultiFPS.Gameplay.Gamemodes.Gamemodes mode,int current)=>mode!=MultiFPS.Gameplay.Gamemodes.Gamemodes.Raid||current<4;
 public static void ResetSession(){groups.Clear();invites.Clear();epochs.Clear();sequence=(uint)UnityEngine.Random.Range(1,int.MaxValue);nextTick=0;}
 public static ChatBehaviour Find(uint id)=>NetworkServer.active&&NetworkServer.spawned.TryGetValue(id,out var n)&&n?n.GetComponent<ChatBehaviour>():null;
 static uint Epoch(uint id)=>epochs.TryGetValue(id,out var value)?value:0;static void Bump(uint id){epochs[id]=Epoch(id)+1;}
 public static bool HasGroup(uint id)=>NetworkServer.active&&groups.ContainsKey(id);public static bool Together(uint a,uint b)=>NetworkServer.active&&groups.TryGetValue(a,out var ga)&&groups.TryGetValue(b,out var gb)&&ReferenceEquals(ga,gb);
 public static uint[] Members(uint id)=>groups.TryGetValue(id,out var g)?g.Members.ToArray():Array.Empty<uint>();
 static void Push(Group g){var ids=g.Members.ToArray();var names=ids.Select(id=>{var p=Find(id);return p?RiftSessionChatTuning.Plain(p.Player.PlayerInfo.Username,24):"Jugador";}).ToArray();foreach(var id in ids){var p=Find(id);if(p)p.PushParty(g.Leader,ids,names);}}
 public static bool Invite(ChatBehaviour from,uint id){if(!NetworkServer.active||!from||!from.Alive||id==from.netId)return false;Tick();var to=Find(id);if(!to||!to.Alive||groups.ContainsKey(id)||to.Player.MyCharacter.gameObject.scene!=from.Player.MyCharacter.gameObject.scene||UnityEngine.Vector3.Distance(to.Player.MyCharacter.transform.position,from.Player.MyCharacter.transform.position)>RiftSessionChatTuning.Load.Radius){from.Status(3);return false;}if(invites.ContainsKey(id)){from.Status(4);return false;}if(!groups.TryGetValue(from.netId,out var g)){g=new Group{Leader=from.netId,Version=1};g.Members.Add(from.netId);groups[from.netId]=g;Bump(from.netId);}if(g.Leader!=from.netId||g.Members.Count>=RiftSessionChatTuning.Load.PartyLimit){from.Status(5);return false;}var invite=new Invitation{From=from.netId,Token=++sequence,Version=g.Version,TargetEpoch=Epoch(id),Group=g,Until=NetworkTime.time+RiftSessionChatTuning.Load.InviteSeconds};invites[id]=invite;to.PushInvite(from.netId,invite.Token,RiftSessionChatTuning.Plain(from.Player.PlayerInfo.Username,24),invite.Until);Push(g);return true;}
 public static bool Accept(ChatBehaviour to,uint from,uint token){if(!NetworkServer.active||!to||!to.Alive||!invites.TryGetValue(to.netId,out var i)||i.From!=from||i.Token!=token)return false;invites.Remove(to.netId);to.PushInvite(0,0,"",0);var inviter=Find(from);if(NetworkTime.time>i.Until||!inviter||!inviter.Ready||groups.ContainsKey(to.netId)||Epoch(to.netId)!=i.TargetEpoch||!groups.TryGetValue(from,out var g)||!ReferenceEquals(g,i.Group)||g.Version!=i.Version||g.Leader!=from||g.Members.Count>=RiftSessionChatTuning.Load.PartyLimit){to.Status(6);return false;}g.Members.Add(to.netId);g.Version++;groups[to.netId]=g;Bump(to.netId);Push(g);return true;}
 public static bool Decline(ChatBehaviour to,uint token){if(!NetworkServer.active||!to||!invites.TryGetValue(to.netId,out var i)||i.Token!=token)return false;invites.Remove(to.netId);to.PushInvite(0,0,"",0);return true;}
 public static void Remove(uint id){if(!NetworkServer.active)return;Bump(id);if(invites.Remove(id)){var p=Find(id);if(p)p.PushInvite(0,0,"",0);}foreach(var key in invites.Where(p=>p.Value.From==id).Select(p=>p.Key).ToArray()){invites.Remove(key);var p=Find(key);if(p)p.PushInvite(0,0,"",0);}if(!groups.TryGetValue(id,out var g))return;groups.Remove(id);g.Members.Remove(id);g.Version++;var removed=Find(id);if(removed)removed.PushParty(0,Array.Empty<uint>(),Array.Empty<string>());if(g.Members.Count==0)return;if(g.Leader==id)g.Leader=g.Members[0];Push(g);}
 public static void Tick(){if(!NetworkServer.active||NetworkTime.time<nextTick)return;nextTick=NetworkTime.time+1;foreach(var id in groups.Keys.ToArray()){var p=Find(id);if(!p||!p.Ready)Remove(id);}foreach(var id in invites.Keys.ToArray()){var p=Find(id);if(!p||!p.Ready||NetworkTime.time>invites[id].Until){invites.Remove(id);if(p)p.PushInvite(0,0,"",0);}}if(groups.Count==0&&invites.Count==0)epochs.Clear();}
}
}
